#!/usr/bin/env python3
"""Emit one Linux scheduler-pressure JSON event to stdout."""
import json
import os
import time


def read_loadavg():
    with open("/proc/loadavg", "r", encoding="ascii") as handle:
        fields = handle.read().split()
    runnable, total = fields[3].split("/", 1)
    return int(runnable), int(total)


def read_cpu_psi():
    with open("/proc/pressure/cpu", "r", encoding="ascii") as handle:
        some = next(line for line in handle if line.startswith("some "))
    values = dict(item.split("=", 1) for item in some.split()[1:])
    return {
        "psi_cpu_some_avg10_pct": float(values["avg10"]),
        "psi_cpu_some_avg60_pct": float(values["avg60"]),
        "psi_cpu_some_avg300_pct": float(values["avg300"]),
        "psi_cpu_some_total_us": int(values["total"]),
    }


event = {
    "event_epoch_s": int(time.time()),
    "collector_schema": 1,
    "collection_status": "ok",
}
try:
    event["runnable_entities"], event["total_entities"] = read_loadavg()
    event["online_cpus"] = int(os.sysconf("SC_NPROCESSORS_ONLN"))
except (OSError, IndexError, ValueError):
    event["collection_status"] = "read_error"
else:
    try:
        event.update(read_cpu_psi())
    except FileNotFoundError:
        event["collection_status"] = "psi_unavailable"
    except (OSError, StopIteration, KeyError, ValueError):
        event["collection_status"] = "read_error"
print(json.dumps(event, separators=(",", ":"), sort_keys=True))
